def count_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 2
            if i * i == n:
                count -= 1
    return count

candidates = {}
for f in range(2, 301):
    d_count = count_divisors(f)
    if d_count > 0:
        candidates[f] = d_count

# Sort by number of divisors (descending), then by F value (ascending)
sorted_candidates = sorted(candidates.items(), key=lambda item: (-item[1], item[0]))

print("F, Divisor Count")
for f, d_count in sorted_candidates:
    print(f"{f}, {d_count}")

# Displaying the top N candidates for a focused list
top_candidates = sorted_candidates[:30]
print("\n--- Top 30 Candidates ---")
for f, d_count in top_candidates:
    print(f"F={f}, Divisors={d_count}")

